CoreIconSprite find_core_icon(std::string_view key) noexcept {
    const uint16_t* pixels = kIconTestPattern;
    if (key == "applewin") {
        pixels = kIconAppleWin;
    } else if (key == "c64" || key == "vice_x64" || key == "vice_x64sc") {
        pixels = kIconC64;
    } else if (key == "quasi88") {
        pixels = kIconQuasi88;
    } else if (key == "np2kai") {
        pixels = kIconNp2kai;
    } else if (key == "bluemsx") {
        pixels = kIconBlueMsx;
    } else if (key == "emuz700") {
        pixels = kIconEmuZ700;
    } else if (key == "fm7" || key == "efm7" || key == "efm77av" || key == "efm77av40") {
        pixels = kIconFm7;
    } else if (key == "msx68k") {
        pixels = kIconMsx68k;
    } else if (key == "g800") {
        pixels = kIconG800;
    } else if (key == "dosbox_pure" || key == "dos") {
        pixels = kIconDosbox;
    } else if (key == "setup") {
        pixels = kIconSetup;
    } else if (key == "quit") {
        pixels = kIconQuit;
    }
    return CoreIconSprite{kCoreIconWidth, kCoreIconHeight, pixels};
}

